       grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # If start is the same as goal
    if start == goal:
        return [start]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Use a recursive approach to explore paths without BFS/DFS
    def dfs(r, c, path):
        if (r, c) == goal:
            return path + [(r, c)]

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in path:
                result = dfs(nr, nc, path + [(r, c)])
                if result:
                    return result
        return None

    return dfs(start[0], start[1], [])

